-- GENERADO por service/scripts/generar_sql_ayuda.py a partir de
-- retroalimentacion/ayuda-preguntas.md — no editar a mano.
--
-- Ayuda de las 50 preguntas del formulario público (definición y preguntas
-- guía). Contenido de trabajo, pendiente de revisión del Dr. Sergio.
-- Requiere la migración 20261117000001.

begin;

update nom036.item set ayuda_definicion = $txt$**Manejo manual de cargas:** levantar, bajar, empujar, jalar, transportar o estibar (apilar) materiales con la fuerza del cuerpo, con o sin ayuda de diablos, carretillas u otros equipos. Para la norma, carga es cualquier objeto de 3 kg o más.$txt$, ayuda_preguntas_guia = array[$txt$¿En qué áreas o puestos se mueven a mano objetos de 3 kg o más?$txt$, $txt$¿La lista incluye empujar, jalar, transportar y estibar, además de levantar?$txt$, $txt$¿Está por escrito y se actualiza cuando cambian los puestos?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Peso de la carga:** cuánto pesa lo que se mueve en cada estación. La norma pide que el procedimiento de seguridad de cada actividad describa la carga: peso, tamaño, forma, agarre y estabilidad.$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha pesado lo que se maneja en cada estación, o solo se calcula a ojo?$txt$, $txt$¿Se sabe cuál es la carga más pesada de cada estación?$txt$, $txt$¿El dato está registrado?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Áreas libres de obstáculos:** los lugares donde se trabaja con cargas y por donde se pasa con ellas deben estar despejados, ordenados y limpios.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay lugares donde haya que esquivar objetos con una carga en las manos?$txt$, $txt$¿El espacio permite girar y acomodar la carga sin posturas forzadas?$txt$, $txt$¿El orden se mantiene todos los días o solo de vez en cuando?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Evaluación rápida (estimación simple del nivel de riesgo):** primera revisión de una tarea con cargas, sin mediciones detalladas, para saber qué tan riesgosa es. Se hace con el Apéndice I de la norma si la tarea es levantar, bajar o transportar, y con el Apéndice II si es empujar o jalar.$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha aplicado el Apéndice I o el II a alguna tarea?$txt$, $txt$¿Se aplicó a todas las tareas con manejo de cargas, o solo a algunas?$txt$, $txt$¿Los resultados están documentados?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Frecuencia:** cuántas veces se levanta o traslada una carga en cierto tiempo, por ejemplo por minuto. La norma pide anotarla al identificar cada tarea con cargas, junto con cuánto dura esa tarea.$txt$, ayuda_preguntas_guia = array[$txt$¿Se sabe cuántas veces por minuto o por hora se levanta o traslada carga en cada tarea?$txt$, $txt$¿Ese dato se midió o es un cálculo de memoria?$txt$, $txt$¿Se registra también cuánto dura la tarea?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Peso máximo por edad y género (Tabla 1 de la norma):** lo más que una persona puede levantar o bajar. Menores de 18 años: 7 kg. De 18 a 45 años: 20 kg mujeres y 25 kg hombres. Mayores de 45: 15 kg mujeres y 20 kg hombres; con aval médico pueden llegar al límite de 18 a 45. Son topes: el peso permitido puede ser menor según la frecuencia, la distancia y el agarre.$txt$, ayuda_preguntas_guia = array[$txt$¿Se conoce la edad y el género de quienes levantan o bajan cargas?$txt$, $txt$¿Alguna carga supera el límite que le corresponde a quien la maneja?$txt$, $txt$¿Esta revisión se hizo por escrito?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Informe del análisis de riesgo:** documento que pide la norma. Entre otros datos, debe decir qué actividades del centro de trabajo implican manejo manual de cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay un documento o plano que indique qué puestos manejan cargas?$txt$, $txt$¿Corresponde a los puestos que existen hoy?$txt$, $txt$¿Se puede consultar cuando se necesita?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Medidas técnicas:** cambios físicos en el lugar de trabajo para reducir el esfuerzo. Por ejemplo, mover máquinas, equipos o materiales para que queden cerca de donde se usan.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay materiales que se trasladan lejos o varias veces sin necesidad?$txt$, $txt$¿Se ha movido algo de lugar para evitar agacharse, girar o estirarse con carga?$txt$, $txt$¿Esos cambios se basaron en un análisis?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Período de descanso:** pausa, contada en minutos, que se da después de una tarea con cargas o entre varias tareas. La norma la incluye entre las medidas administrativas, es decir, cambios en la forma de organizar el trabajo.$txt$, ayuda_preguntas_guia = array[$txt$¿Las tareas repetitivas con cargas tienen pausas definidas?$txt$, $txt$¿Las pausas están programadas o dependen de cada persona?$txt$, $txt$¿Se respetan en la práctica?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Masa acumulada:** el total de kilos que una persona transporta a mano durante su jornada. La norma pone un tope por jornada de 8 horas: 10,000 kg si los traslados son de menos de 10 m, o 6,000 kg si son de hasta 20 m.$txt$, ayuda_preguntas_guia = array[$txt$¿Se sabe cuántos kilos transporta a mano cada trabajador en un turno?$txt$, $txt$¿Alguna persona se acerca a esos topes?$txt$, $txt$¿Ese total se controla o se registra?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 1);
update nom036.item set ayuda_definicion = $txt$**Equipos auxiliares:** carretillas, diablos, patines y otros equipos con ruedas y sin motor que el trabajador empuja o sostiene para mover material en distancias cortas.$txt$, ayuda_preguntas_guia = array[$txt$¿Los puestos que mueven cargas tienen equipo auxiliar a la mano?$txt$, $txt$¿El personal lo usa de verdad, o solo existe?$txt$, $txt$¿Hay cargas pesadas que se siguen moviendo a mano?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Estabilidad de la carga:** que la carga no se mueva, no se ladee y no se caiga durante el traslado. La norma pide asegurarla al empujar o jalar y, cuando haga falta, sujetarla (con cinchos, flejes o similares).$txt$, ayuda_preguntas_guia = array[$txt$¿Se revisa que la carga esté bien acomodada y sujeta antes de moverla?$txt$, $txt$¿Ha habido cargas que se caen del equipo durante el traslado?$txt$, $txt$¿Hay una forma establecida de hacer esa revisión?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Capacidad de carga (capacidad nominal):** el peso máximo que un diablo, patín o carretilla puede llevar con seguridad, según su fabricante. La norma pide verificar que la carga no lo rebase.$txt$, ayuda_preguntas_guia = array[$txt$¿Se sabe cuánto peso soporta cada diablo, patín o carretilla?$txt$, $txt$¿Esa capacidad está marcada en el equipo o registrada?$txt$, $txt$¿Se verifica que no se cargue de más?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Superficie de rodamiento:** el piso por donde pasan las ruedas del equipo auxiliar. La norma pide revisarlo antes de mover cargas, evitar pisos ranurados, dañados o resbalosos y quitar los obstáculos.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay baches, desniveles, grietas o rejillas en las rutas de traslado?$txt$, $txt$¿Los pisos suelen estar limpios y secos?$txt$, $txt$¿Se revisan antes de mover cargas?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Espacio de maniobra:** el lugar necesario para dar vuelta o girar con la carga. La norma pide revisar de antemano que alcance para el tamaño de la carga, sobre todo en pasillos angostos.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay pasillos donde no se puede girar con el equipo cargado?$txt$, $txt$¿Peatones y cargas comparten el pasillo de forma segura?$txt$, $txt$¿Los pasillos se revisan de forma periódica?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Rampas y pendientes:** la norma pide evitarlas en la ruta de traslado. Si no se puede, quien maneja el diablo, patín o carretilla queda del lado de arriba: al subir va delante jalándolo y al bajar va detrás sosteniéndolo. La señalización ayuda a usarlas con seguridad.$txt$, ayuda_preguntas_guia = array[$txt$¿Las rampas y plataformas tienen señalización visible?$txt$, $txt$¿Hay carriles pintados o indicaciones del sentido de circulación?$txt$, $txt$¿La señalización está en buen estado?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Condiciones seguras del equipo:** que las ruedas, frenos, estructura y asas del equipo auxiliar estén en buen estado. La norma pide revisarlo antes de empezar a trabajar con él.$txt$, ayuda_preguntas_guia = array[$txt$¿Alguien revisa ruedas, frenos y estructura de los equipos?$txt$, $txt$¿Esa revisión tiene una frecuencia definida?$txt$, $txt$¿El equipo dañado se repara o se retira?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Reparto de la carga:** acomodar el peso de forma pareja en el equipo auxiliar para que no se ladee ni se vuelque y sea más fácil de mover. Es parte de lo que la norma pide para que la carga se mantenga estable.$txt$, ayuda_preguntas_guia = array[$txt$¿Lo más pesado se acomoda abajo y al centro?$txt$, $txt$¿El personal sabe cómo repartir la carga?$txt$, $txt$¿Ha habido volcaduras o cargas inestables?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Condiciones del ambiente:** características del lugar, como ruido, calor, frío o poca luz, que hacen más pesado el trabajo o lo vuelven peligroso. La norma pide tomarlas en cuenta en el procedimiento de seguridad.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay zonas con poca luz, mucho calor o mucho ruido en las rutas de traslado?$txt$, $txt$¿Esas zonas están identificadas por escrito?$txt$, $txt$¿Se tomaron medidas para ellas?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Masa acumulada:** el total de kilos que una persona transporta a mano durante su jornada. La norma pone un tope por jornada de 8 horas: 10,000 kg si los traslados son de menos de 10 m, o 6,000 kg si son de hasta 20 m.$txt$, ayuda_preguntas_guia = array[$txt$¿Existe un límite de kilos por jornada para quien transporta materiales?$txt$, $txt$¿Se distingue cuánto de ese peso se mueve a mano y cuánto con equipo auxiliar?$txt$, $txt$¿Se verifica que se respete?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 2);
update nom036.item set ayuda_definicion = $txt$**Capacitación:** la norma pide enseñar al personal que maneja cargas, de acuerdo con sus tareas: qué daños a la salud puede causar, cómo reconocer los riesgos, qué dice la norma y cómo trabajar de forma segura.$txt$, ayuda_preguntas_guia = array[$txt$¿Todo el personal que maneja cargas recibió capacitación sobre cómo hacerlo de forma segura?$txt$, $txt$¿Fue específica para sus tareas o general?$txt$, $txt$¿El personal de nuevo ingreso la recibe antes de empezar?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Registro de capacitación:** la norma pide anotar, como mínimo, el nombre y puesto de cada trabajador capacitado, la fecha, los temas y el nombre del instructor.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay una lista de quién se capacitó y cuándo?$txt$, $txt$¿Incluye los temas y al instructor?$txt$, $txt$¿Está al día?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Partes de la capacitación:** la norma pide que tenga teoría (explicación), práctica (hacer la tarea con guía del instructor) y una evaluación de lo aprendido.$txt$, ayuda_preguntas_guia = array[$txt$¿La capacitación incluye práctica, no solo explicación?$txt$, $txt$¿Se evalúa lo aprendido?$txt$, $txt$¿Se hace así en todas las sesiones?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Empujar y jalar (tracción) cargas:** mover una carga de forma horizontal, a mano o con diablo, patín o carretilla. Al empujar, la fuerza se aleja del cuerpo; al jalar, va hacia el cuerpo.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal de almacén sabe empujar y jalar sin forzar la espalda?$txt$, $txt$¿Se le ha enseñado a usar diablos, patines y carretillas en rampas?$txt$, $txt$¿Esa capacitación incluyó práctica?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Aptitud física:** que la salud de una persona le permita manejar cargas sin riesgo. La norma pide que la avale un médico (de la empresa, de una institución de seguridad social o privada) y que haya un examen médico inicial.$txt$, ayuda_preguntas_guia = array[$txt$¿Se hace un examen médico antes de asignar a alguien a tareas con cargas?$txt$, $txt$¿Ese examen evalúa específicamente el manejo de cargas?$txt$, $txt$¿Los resultados quedan registrados?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Vigilancia a la salud:** revisiones médicas al personal que maneja cargas, hechas por un médico con conocimientos en medicina del trabajo. La norma pide seguimiento cada año, o antes si aparecen señales de una lesión en músculos, huesos o articulaciones.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal expuesto tiene revisión médica al menos una vez al año?$txt$, $txt$¿Se revisa antes si alguien reporta dolor o molestias?$txt$, $txt$¿La realiza un médico con conocimientos en medicina del trabajo?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Restricción médica:** indicación del médico de que una persona no debe hacer cierta tarea con cargas o de que necesita un tiempo de recuperación. Según la norma, solo el médico determina la aptitud física.$txt$, ayuda_preguntas_guia = array[$txt$¿Ha habido personal con restricción médica para cargar?$txt$, $txt$¿Se le asignó otra tarea compatible con su salud?$txt$, $txt$¿Hay una forma establecida de hacerlo?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Hábitos posturales:** la forma de colocar y mover el cuerpo al trabajar. Por ejemplo, doblar las rodillas al levantar, mantener la carga pegada al cuerpo y no girar el tronco con peso.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay campañas, carteles o pláticas sobre posturas al cargar?$txt$, $txt$¿Se repiten de forma periódica?$txt$, $txt$¿Llegan a todo el personal?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Reforzar la capacitación:** volver a darla o actualizarla cada cierto tiempo. También antes de ese plazo si llegan herramientas o equipo nuevo, cambian las condiciones de trabajo, se detectan condiciones inseguras o la última evaluación del personal lo sugiere.$txt$, ayuda_preguntas_guia = array[$txt$¿Cuándo fue la última capacitación del personal expuesto?$txt$, $txt$¿Se repite cada año?$txt$, $txt$¿Se vuelve a dar cuando cambia el proceso o llega equipo nuevo?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Fatiga:** cansancio físico o mental por un esfuerzo excesivo, que desaparece por completo con el descanso. Cuidar el bienestar del personal incluye prevenirla y evitar la sobrecarga de trabajo.$txt$, ayuda_preguntas_guia = array[$txt$¿Se toma en cuenta el cansancio del personal al asignar tareas pesadas?$txt$, $txt$¿El personal puede reportar malestar o exceso de trabajo?$txt$, $txt$¿Se actúa cuando lo reporta?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 3);
update nom036.item set ayuda_definicion = $txt$**Política interna:** documento de la empresa que declara su compromiso de prevenir riesgos ergonómicos y fija reglas generales para cumplirlo.$txt$, ayuda_preguntas_guia = array[$txt$¿Existe por escrito?$txt$, $txt$¿La respalda la dirección?$txt$, $txt$¿El personal la conoce?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Responsable del cumplimiento:** persona o área encargada de dar seguimiento, dentro del centro de trabajo, a lo que pide la NOM-036-1-STPS-2018.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay una persona o un área a cargo de la norma?$txt$, $txt$¿Su designación es oficial?$txt$, $txt$¿Tiene tiempo y recursos para hacerlo?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Presupuesto para equipos auxiliares:** dinero apartado de forma planeada para comprar o renovar carretillas, diablos, patines y otros equipos para mover cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay una partida para estos equipos?$txt$, $txt$¿Se planea cada año o solo se compra cuando algo falla?$txt$, $txt$¿Se usó en el último año?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Registros:** la norma pide guardar evidencia de las medidas preventivas que se aplicaron y de los exámenes médicos. El expediente médico se conserva al menos cinco años.$txt$, ayuda_preguntas_guia = array[$txt$¿Se guardan los diagnósticos, programas y acciones de ergonomía?$txt$, $txt$¿Están actualizados?$txt$, $txt$¿Se pueden consultar con facilidad?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Supervisión:** revisar en el área de trabajo que las tareas con cargas se hagan de forma segura, siguiendo el procedimiento de seguridad de cada actividad.$txt$, ayuda_preguntas_guia = array[$txt$¿Alguien revisa en el área de trabajo que se apliquen las medidas?$txt$, $txt$¿Con qué frecuencia?$txt$, $txt$¿Hay un formato o criterio para hacerlo?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Auditoría de cumplimiento:** revisión de qué tanto cumple la empresa con la norma. Puede hacerla personal de la propia empresa (interna) o una unidad de verificación acreditada y aprobada (externa). Contratar una unidad de verificación es opcional.$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha revisado alguna vez el cumplimiento de la norma?$txt$, $txt$¿La revisión fue interna o externa?$txt$, $txt$¿Se atendieron sus hallazgos?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Informar al personal:** la norma pide explicar a los trabajadores qué daños a la salud puede causar el manejo manual de cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal sabe qué es la NOM-036 y por qué importa?$txt$, $txt$¿Se usan carteles, pláticas o boletines?$txt$, $txt$¿Se hace de forma regular?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Acceso al análisis de riesgo:** la norma pide que el análisis de riesgo esté disponible para todos los trabajadores que manejan cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal puede consultar los riesgos de su puesto?$txt$, $txt$¿La información está en un lugar y formato accesibles?$txt$, $txt$¿Se le avisa dónde encontrarla?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Diagnóstico de seguridad y salud en el trabajo:** revisión general de los peligros y riesgos del centro de trabajo que pide otra norma, la NOM-030-STPS-2009. La NOM-036 pide que el análisis de riesgo por manejo de cargas forme parte de ese diagnóstico.$txt$, ayuda_preguntas_guia = array[$txt$¿El diagnóstico ergonómico forma parte del diagnóstico o programa de seguridad y salud?$txt$, $txt$¿Se actualizan juntos?$txt$, $txt$¿Las acciones de ergonomía aparecen en ese programa?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Cultura de prevención:** que prevenir riesgos y cuidar la ergonomía sea parte de la forma habitual de trabajar, con participación de la dirección y del personal.$txt$, ayuda_preguntas_guia = array[$txt$¿La dirección participa en las acciones de ergonomía?$txt$, $txt$¿El personal propone mejoras?$txt$, $txt$¿Hay actividades de prevención de forma continua?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 4);
update nom036.item set ayuda_definicion = $txt$**Análisis de los factores de riesgo ergonómico:** revisión de lo que en el trabajo puede causar sobreesfuerzo, movimientos repetitivos o posturas forzadas. Según la norma tiene tres pasos: identificar las tareas con cargas, hacer una evaluación rápida de su riesgo y, si hace falta, una evaluación detallada.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay un diagnóstico centrado en el manejo manual de cargas?$txt$, $txt$¿Incluye la identificación de tareas y la evaluación de su riesgo?$txt$, $txt$¿Está por escrito?$txt$]::text[]
  where numero = 1 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Evaluación específica (detallada):** valoración a fondo del riesgo con un método científicamente validado, como la ecuación de NIOSH o la ISO 11228-2 para empujar o jalar. Se usa cuando la evaluación rápida no es suficiente o cuando sigue habiendo peligro después de aplicar medidas. También puede hacerse desde el principio.$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha aplicado algún método formal de evaluación a algún puesto?$txt$, $txt$¿Lo aplicó una persona capacitada?$txt$, $txt$¿Los resultados se usaron para decidir medidas?$txt$]::text[]
  where numero = 2 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Medidas técnicas:** cambios en la forma de trabajar o en el lugar para reducir el esfuerzo, como modificar procedimientos, instalaciones, máquinas o equipos, o redistribuir espacios. La norma pide aplicarlas cuando el análisis de riesgo lo indica.$txt$, ayuda_preguntas_guia = array[$txt$¿Se han hecho cambios físicos para reducir el esfuerzo?$txt$, $txt$¿Se basaron en el análisis de riesgo?$txt$, $txt$¿Se revisó si funcionaron?$txt$]::text[]
  where numero = 3 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Medidas administrativas:** cambios en la organización del trabajo, como limitar el tiempo o las veces que se hace una tarea, programar descansos, variar las actividades o rotar al personal.$txt$, ayuda_preguntas_guia = array[$txt$¿Hay rotación de puestos o pausas programadas?$txt$, $txt$¿Están por escrito?$txt$, $txt$¿Se aplican en todos los turnos?$txt$]::text[]
  where numero = 4 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Programa de ergonomía:** plan por escrito que, según la norma, dice qué puestos incluye, qué medidas se aplicarán, en qué fechas (no más de un año), quién es responsable, cómo se controla el avance y cómo se evalúa el resultado.$txt$, ayuda_preguntas_guia = array[$txt$¿Existe un programa de ergonomía por escrito?$txt$, $txt$¿Tiene responsables y fechas?$txt$, $txt$¿Se le da seguimiento?$txt$]::text[]
  where numero = 5 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Trastorno musculoesquelético laboral:** lesión o enfermedad de músculos, huesos, tendones o articulaciones causada por el trabajo, por ejemplo por sobreesfuerzo, movimientos repetitivos o posturas forzadas.$txt$, ayuda_preguntas_guia = array[$txt$¿Se registran los casos de dolor o lesión relacionados con el manejo de cargas?$txt$, $txt$¿Se les da seguimiento médico?$txt$, $txt$¿Se revisan las tareas de quien presenta un caso?$txt$]::text[]
  where numero = 6 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Cuestionario Nórdico de Kuorinka:** cuestionario sobre molestias en distintas partes del cuerpo. La norma lo propone como opción, no como obligación, para detectar a tiempo posibles trastornos musculoesqueléticos.$txt$, ayuda_preguntas_guia = array[$txt$¿Se ha aplicado algún cuestionario sobre molestias o dolor al personal?$txt$, $txt$¿A todo el personal expuesto?$txt$, $txt$¿Se analizaron las respuestas?$txt$]::text[]
  where numero = 7 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Mejora continua:** revisar cada cierto tiempo los resultados de las acciones de ergonomía para corregir lo que no funciona y mantener lo que sí.$txt$, ayuda_preguntas_guia = array[$txt$¿Se reportan los avances en ergonomía?$txt$, $txt$¿Con qué frecuencia?$txt$, $txt$¿Esos reportes llevan a nuevas acciones?$txt$]::text[]
  where numero = 8 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Síntomas musculoesqueléticos:** molestias como dolor, hormigueo, rigidez o pérdida de fuerza en espalda, cuello, hombros, brazos o piernas. La norma pide que la capacitación explique los daños a la salud que puede causar el manejo de cargas.$txt$, ayuda_preguntas_guia = array[$txt$¿El personal sabe reconocer las primeras molestias?$txt$, $txt$¿Sabe a quién reportarlas?$txt$, $txt$¿Esto se incluye en la capacitación?$txt$]::text[]
  where numero = 9 and criterio_id = (select id from nom036.criterio where numero = 5);
update nom036.item set ayuda_definicion = $txt$**Medidas de control en el programa:** la norma pide que el programa de ergonomía diga qué medidas técnicas (cambios en el lugar o el equipo) y administrativas (cambios en la organización del trabajo) se van a aplicar.$txt$, ayuda_preguntas_guia = array[$txt$¿El programa dice qué medidas se aplicarán y en qué puestos?$txt$, $txt$¿Están descritas con claridad para quien las aplica?$txt$, $txt$¿Se actualizan cuando cambian las condiciones?$txt$]::text[]
  where numero = 10 and criterio_id = (select id from nom036.criterio where numero = 5);

commit;
